def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    tokens_re = re.compile(
        r"\s*(<=|>=|<>|[()+\-*/,:=<>]|[A-Za-z]+|[0-9]+)"
    )

    def tokenize(text):
        tokens = []
        pos = 0
        while pos < len(text):
            match = tokens_re.match(text, pos)
            if not match:
                raise ValueError("Invalid formula")
            tokens.append(match.group(1))
            pos = match.end()
        return tokens

    cache = {}
    active = set()

    def cell_value(name):
        if name not in cells:
            return 0
        if name in cache:
            return cache[name]
        if name in active:
            return "#CYCLE!"

        active.add(name)
        content = cells[name]
        if not content.startswith("="):
            value = int(content)
        else:
            parser = Parser(tokenize(content[1:]))
            value = parser.parse()
        active.remove(name)
        cache[name] = value
        return value

    def is_error(value):
        return isinstance(value, str)

    class Parser:
        def __init__(self, tokens):
            self.tokens = tokens
            self.pos = 0

        def peek(self):
            return self.tokens[self.pos] if self.pos < len(self.tokens) else None

        def take(self):
            token = self.peek()
            self.pos += 1
            return token

        def parse(self):
            return self.parse_add()

        def parse_add(self):
            value = self.parse_mul()
            while self.peek() in ("+", "-"):
                op = self.take()
                if is_error(value):
                    return value
                right = self.parse_mul()
                if is_error(right):
                    return right
                value = value + right if op == "+" else value - right
            return value

        def parse_mul(self):
            value = self.parse_unary()
            while self.peek() in ("*", "/"):
                op = self.take()
                if is_error(value):
                    return value
                right = self.parse_unary()
                if is_error(right):
                    return right
                if op == "*":
                    value *= right
                elif right == 0:
                    value = "#DIV/0!"
                else:
                    quotient = abs(value) // abs(right)
                    value = -quotient if (value < 0) != (right < 0) else quotient
            return value

        def parse_unary(self):
            if self.peek() == "-":
                self.take()
                value = self.parse_unary()
                return value if is_error(value) else -value
            return self.parse_atom()

        def parse_atom(self):
            token = self.take()
            if token == "(":
                value = self.parse_add()
                self.take()  # )
                return value
            if token is None:
                raise ValueError("Unexpected end of formula")
            if token.isdigit():
                return int(token)

            if self.peek() == "(":
                function = token.upper()
                self.take()
                if function == "IF":
                    left = self.parse_add()
                    op = self.take()
                    right = self.parse_add()
                    self.take()  # comma
                    then_value = self.parse_add()
                    self.take()  # comma
                    else_start = self.pos

                    if is_error(left):
                        return left
                    if is_error(right):
                        return right
                    condition = {
                        "=": left == right,
                        "<>": left != right,
                        "<": left < right,
                        "<=": left <= right,
                        ">": left > right,
                        ">=": left >= right,
                    }[op]
                    if condition:
                        self.pos = else_start
                        return then_value
                    return self.parse_add()

                args = []
                if self.peek() != ")":
                    while True:
                        args.append(self.parse_function_arg())
                        if self.peek() != ",":
                            break
                        self.take()
                self.take()  # )

                values = []
                for kind, arg in args:
                    if kind == "formula":
                        value = arg
                        if is_error(value):
                            return value
                        values.append(value)
                    else:
                        for row in range(arg[0], arg[2] + 1):
                            for col in range(arg[1], arg[3] + 1):
                                name = chr(ord("A") + col) + str(row)
                                if name in cells:
                                    value = cell_value(name)
                                    if is_error(value):
                                        return value
                                    values.append(value)

                if function == "SUM":
                    return sum(values)
                if not values:
                    return 0
                if function == "MIN":
                    return min(values)
                return max(values)

            if len(token) >= 2 and token[0].isalpha() and token[1:].isdigit():
                return cell_value(token)
            raise ValueError("Invalid atom")

        def parse_function_arg(self):
            # A range starts with a cell name followed by ':'.
            if (
                self.pos + 1 < len(self.tokens)
                and re.fullmatch(r"[A-Z][1-9][0-9]?", self.tokens[self.pos])
                and self.tokens[self.pos + 1] == ":"
            ):
                first = self.take()
                self.take()
                second = self.take()
                c1, r1 = ord(first[0]) - ord("A"), int(first[1:])
                c2, r2 = ord(second[0]) - ord("A"), int(second[1:])
                return "range", (
                    min(r1, r2),
                    min(c1, c2),
                    max(r1, r2),
                    max(c1, c2),
                )
            return "formula", self.parse_add()

    return {name: cell_value(name) for name in cells}
